    int j = arr.length - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }
    swap(arr, i, j);
    j = arr.length - 1;
    while (i < j) {
        swap(arr, i, j);
        i++;
        j--;
    }
    return true;
}

// Utility function to swap two elements in an array
static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}
